SELECT i.id, i.sku_id, i.warehouse_id, i.quantity, i.reserved_qty, i.global_reserved_qty, i.alert_threshold, i.version, i.tenant_id, i.update_time, ps.sku_code, ps.price, p.name AS product_name, p.category_id, pc.color_name, psz.size_code AS size_name, w.warehouse_name FROM inventory i INNER JOIN product_sku ps ON i.sku_id = ps.id AND i.tenant_id = ps.tenant_id INNER JOIN product p ON ps.product_id = p.id AND ps.tenant_id = p.tenant_id LEFT OUTER JOIN product_color pc ON ps.color_id = pc.id AND ps.tenant_id = pc.tenant_id LEFT OUTER JOIN product_size psz ON ps.size_id = psz.id AND ps.tenant_id = psz.tenant_id LEFT OUTER JOIN warehouse w ON i.warehouse_id = w.id AND i.tenant_id = w.tenant_id WHERE i.tenant_id = #{tenantId}
AND i.warehouse_id = #{warehouseId}
AND (i.quantity - i.reserved_qty - i.global_reserved_qty) < i.alert_threshold
AND (i.quantity - i.reserved_qty - i.global_reserved_qty) >= i.alert_threshold
AND (p.name LIKE CONCAT('%', #{keyword}, '%') OR ps.sku_code LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY i.id DESC LIMIT #{offset}, #{size}

SELECT COUNT(*) FROM inventory i INNER JOIN product_sku ps ON i.sku_id = ps.id AND i.tenant_id = ps.tenant_id INNER JOIN product p ON ps.product_id = p.id AND ps.tenant_id = p.tenant_id WHERE i.tenant_id = #{tenantId}
AND i.warehouse_id = #{warehouseId}
AND (i.quantity - i.reserved_qty - i.global_reserved_qty) < i.alert_threshold
AND (i.quantity - i.reserved_qty - i.global_reserved_qty) >= i.alert_threshold
AND (p.name LIKE CONCAT('%', #{keyword}, '%') OR ps.sku_code LIKE CONCAT('%', #{keyword}, '%'))
